import{_ as o,o as e,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Nobody Knows What PGs are Good For, Only I Do - Danil Kipnis, 1&1 IONOS Cloud GmbH","description":"","frontmatter":{"title":"Nobody Knows What PGs are Good For, Only I Do - Danil Kipnis, 1&1 IONOS Cloud GmbH","date":"2019-06-10T00:00:00.000Z","updated":"2019-06-11T00:00:00.000Z","tags":["分布式存储","Ceph","PG间接层","数据冗余","故障恢复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Nobody_Knows_What_PGs_are_Good_For_Only_I_Do_-_Danil_Kipnis_1_1_IONOS_Cloud_GmbH.md","filePath":"posts/2019/Nobody_Knows_What_PGs_are_Good_For_Only_I_Do_-_Danil_Kipnis_1_1_IONOS_Cloud_GmbH.md","lastUpdated":1780459816000}'),t={name:"posts/2019/Nobody_Knows_What_PGs_are_Good_For_Only_I_Do_-_Danil_Kipnis_1_1_IONOS_Cloud_GmbH.md"};function r(n,a,_,s,h,d){return e(),l("div",null,[...a[0]||(a[0]=[i('<p>会议纪要</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>分布式存储架构讨论及Ceph相关技术探讨</p><h3 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h3><p>Daniel（Iona云服务基础设施团队）</p><h3 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h3><h4 id="一、iona云服务架构介绍" tabindex="-1">一、Iona云服务架构介绍 <a class="header-anchor" href="#一、iona云服务架构介绍" aria-label="Permalink to &quot;一、Iona云服务架构介绍&quot;">​</a></h4><p>Iona云服务为每个客户虚拟机提供两个不同的存储机器，并通过网络导出到虚拟机管理器，形成RAID 1。这种架构通过增加新的存储机器对来扩展集群规模，并需要迁移旧卷以平衡集群负载。</p><h4 id="二、分布式存储面临的挑战" tabindex="-1">二、分布式存储面临的挑战 <a class="header-anchor" href="#二、分布式存储面临的挑战" aria-label="Permalink to &quot;二、分布式存储面临的挑战&quot;">​</a></h4><ol><li><strong>数据冗余与故障影响</strong>： 如果每个卷分散在所有机器上，虽然提高了读写吞吐量，但集群中任何故障都可能影响所有客户卷。</li><li><strong>数据共享与恢复风险</strong>： 如果每个磁盘的数据与集群中的其他磁盘共享，虽然提高了读写吞吐量，但在恢复过程中其他磁盘发生故障的概率也较高。</li></ol><h4 id="三、ceph-pg间接层解决方案" tabindex="-1">三、Ceph PG间接层解决方案 <a class="header-anchor" href="#三、ceph-pg间接层解决方案" aria-label="Permalink to &quot;三、Ceph PG间接层解决方案&quot;">​</a></h4><ol><li><strong>PG间接层</strong>： 通过在集群中引入PG（Placement Group）间接层，可以解决上述问题。PG间接层通过以下方式实现： <ul><li><strong>数据分布控制</strong>： 控制数据分布到物理设备上的数量，实现数据冗余。</li><li><strong>去聚类控制</strong>： 控制恢复单个故障设备所需的时间，以及该设备与其他设备共享数据的数量。</li></ul></li><li><strong>PG间接层的优势</strong>： <ul><li>提供了数据分布和去聚类的控制能力。</li><li>是实现关键复制策略和集群扩展的通用框架。</li></ul></li></ol><h4 id="四、ceph集群配置示例" tabindex="-1">四、Ceph集群配置示例 <a class="header-anchor" href="#四、ceph集群配置示例" aria-label="Permalink to &quot;四、Ceph集群配置示例&quot;">​</a></h4><ol><li><strong>RPG（Replication Placement Group）</strong>： RPG位于RADOS对象之上，通过哈希映射到放置组，放置组存储在OSD上。</li><li><strong>客户卷配置</strong>： 每个客户卷通过网络协议（如SRP、iSCSI）导出到客户端，客户端在本地构建RAID数组，并使用与Crash相同的配置方法来管理此类配置。</li></ol><h4 id="五、会议结论" tabindex="-1">五、会议结论 <a class="header-anchor" href="#五、会议结论" aria-label="Permalink to &quot;五、会议结论&quot;">​</a></h4><ol><li>Ceph PG间接层是解决分布式存储面临挑战的有效方法。</li><li>需要进一步研究和探讨Ceph集群配置和优化策略。</li></ol><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ol><li>Daniel将继续研究Ceph集群配置和优化策略。</li><li>团队将关注Ceph社区动态，学习借鉴最佳实践。</li></ol>',18)])])}const u=o(t,[["render",r]]);export{c as __pageData,u as default};
